#pragma once

// Provenance (constraint 3): logic port of archive MURMUR-RUST
// spool/keyring.rs (keys.enc v3 envelope) + spool/crypto.rs
// (derive_protector: direct-HKDF + Argon2id) + the rotate/persist
// ordering of keyring.rs rotate_persisted. The FORMAT is reused
// byte-exact (header/body/AAD/info layouts); the CODE is C++ because
// the VFS storage layer owns all key material and builds without any
// Rust toolchain (lead ruling I; murmur_rust links only under
// SQLITE_MURMUR_ENABLE_MURMUR). Behavior proof: tests/keyring.cpp
// opens fixtures generated by an independent Python implementation
// (/tmp/gen_keyring_vectors.py; seeds embedded in the test) plus
// internal round-trip and tamper matrices.
// KDF params live in the envelope header, not murmur_config
// (chicken-and-egg: params unlock the DB — ruling J exception).
// Envelope bytes live in the `meta:keyring` RocksDB meta key beside
// `meta:cipher` (inside the DB dir, no sidecar); the meta read/write
// at Store::start is a lead merge, this file is pure bytes + crypto.

#include <cstdint>
#include <sqlite3.h>
#include <string>
#include <vector>

#define SQLITE_MURMUR_KEYS_MAGIC "SPLK"
#define SQLITE_MURMUR_KEYS_VERSION 3
#define SQLITE_MURMUR_KDF_DIRECT_HKDF 0
#define SQLITE_MURMUR_KDF_ARGON2ID 1
// Archive Argon2id defaults (crypto.rs ARGON_*).
#define SQLITE_MURMUR_ARGON_TIME 3
#define SQLITE_MURMUR_ARGON_MEMORY_KIB 65536
#define SQLITE_MURMUR_ARGON_THREADS 4
#define SQLITE_MURMUR_KEYS_META "meta:keyring"

// 1 when linked with an Argon2 unit (vendored reference implementation,
// ruling I); 0 — KDF_ARGON2ID envelopes fail closed — otherwise.
int sqlite_murmur_keyring_has_argon2();

struct sqlite_murmur_key_entry {
    std::uint32_t id = 0;
    std::int64_t created_nanos = 0;
    bool active = false;
    unsigned char key[32] = {0};
};

// Unlocked envelope. Holds live key material: destroy with
// sqlite_murmur_keyring_destroy (wipes) once installed/copied.
struct sqlite_murmur_keyring {
    std::uint64_t seq = 0;
    std::uint8_t kdf = SQLITE_MURMUR_KDF_DIRECT_HKDF;
    std::uint32_t argon_time = 0;
    std::uint32_t argon_memory_kib = 0;
    std::uint8_t argon_threads = 0;
    unsigned char context[16] = {0};
    std::string wrap_id;
    std::vector<sqlite_murmur_key_entry> keys; // sorted by id
    std::uint32_t current = 0;                 // highest active id
};

void sqlite_murmur_keyring_destroy(sqlite_murmur_keyring &ring);

// Open + authenticate an envelope. Exactly one of master_key (32 bytes,
// KDF direct) or passphrase (KDF argon2id, NUL-terminated) must be set,
// matching the header KDF. store_id/context_id bind (16 bytes each).
// SQLITE_OK: ring populated. SQLITE_AUTH: protector wrong (seal open
// failed). SQLITE_CORRUPT: structural/authenticated-identity failure
// (magic/version/size/count/CRC/context mismatch, no active key).
// SQLITE_ERROR: KDF argon2id without an Argon2 unit, or bad argon2
// params. SQLITE_MISUSE: bad arguments.
int sqlite_murmur_keyring_open(const unsigned char *envelope, std::size_t len,
                               const unsigned char *master_key,
                               const char *passphrase,
                               const unsigned char store_id[16],
                               const unsigned char context_id[16],
                               sqlite_murmur_keyring &out);

// Create a fresh envelope: single active key id 1, sequence 1, fresh
// salt/nonce/key material. KDF params as stored in the header (direct:
// zeros; argon2id: requested values, requires the Argon2 unit).
// SQLITE_MISUSE on bad arguments (wrap_id > 128 bytes included).
int sqlite_murmur_keyring_create(
    std::uint8_t kdf, std::uint32_t argon_time, std::uint32_t argon_memory_kib,
    std::uint8_t argon_threads, const char *wrap_id,
    const unsigned char store_id[16], const unsigned char context_id[16],
    const unsigned char *master_key, const char *passphrase,
    std::string &envelope_out);

// Stage a successor key and seal the new envelope WITHOUT installing it
// (archive rotate_persisted ordering): the caller persists envelope_out
// to meta:keyring first (single atomic Put) and only then installs it
// by opening the new bytes. Previous current key retires; sequence
// bumps; salt/nonce fresh. Fails closed (no output) on any error.
int sqlite_murmur_keyring_rotate(const sqlite_murmur_keyring &ring,
                                 const unsigned char store_id[16],
                                 const unsigned char *master_key,
                                 const char *passphrase,
                                 std::string &envelope_out,
                                 std::uint32_t &new_id_out);

// Look up unlocked material (NULL when absent). Borrows from ring.
const unsigned char *sqlite_murmur_keyring_current(
    const sqlite_murmur_keyring &ring, std::uint32_t &id_out);
const unsigned char *sqlite_murmur_keyring_by_id(
    const sqlite_murmur_keyring &ring, std::uint32_t id);

// Drop retired keys and re-seal (prune support; WP-D slice D2b). Every
// id in drop must name a retired key: current/active, unknown, empty,
// and drop-everything sets are rejected. Sequence bumps, salt/nonce
// fresh, KDF/params unchanged. The caller persists envelope_out to
// meta:keyring before installing (same persist-then-install ordering
// as rotate). Fail-closed (no output) on any error.
int sqlite_murmur_keyring_drop_keys(const sqlite_murmur_keyring &ring,
                                    const std::uint32_t *drop, std::size_t n,
                                    const unsigned char store_id[16],
                                    const unsigned char *master_key,
                                    const char *passphrase,
                                    std::string &envelope_out);
